import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { texture, uv, vec3, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design tokens
  const colors = {
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
    surface: new THREE.Color('#0b0b10')
  };

  // Create plane geometry for button background
  const planeGeometry = new THREE.PlaneGeometry(1.2, 0.8);

  // Load and configure brushed-metal texture
  const brushedMetalTexture = ctx.textureLoader.load(
    '/prism-assets/chrome/brushed-metal.map.png'
  );
  brushedMetalTexture.colorSpace = THREE.SRGBColorSpace;

  // Build TSL shader: gradient surface + metal texture composite
  const uvNode = uv();

  // Vertical gradient: paper (bottom) to surface (top)
  const paperVec = vec3(
    colors.paper.r,
    colors.paper.g,
    colors.paper.b
  );
  const surfaceVec = vec3(
    colors.surface.r,
    colors.surface.g,
    colors.surface.b
  );
  const gradientNode = mix(paperVec, surfaceVec, uvNode.y);

  // Sample metal texture
  const metalNode = texture(brushedMetalTexture, uvNode);

  // Composite: blend gradient and metal (30% metal opacity for engineered surface effect)
  const compositeNode = mix(gradientNode, metalNode, 0.3);

  // Create material with composite shader
  const planeMaterial = new MeshBasicNodeMaterial({
    colorNode: compositeNode,
    transparent: true
  });

  // Create mesh and add to group
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Create text content using fontAtlas
  if (ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.create({
      text: 'Get started',
      fontSize: 42,
      fontWeight: 400,
      fontFamily: 'Lora',
      color: colors.ink,
      align: 'center',
      anchorX: 'center',
      anchorY: 'middle'
    });

    if (textMesh) {
      textMesh.position.z = 0.01; // Render above plane surface
      group.add(textMesh);
    }
  }

  // Apply scene placement from config
  group.position.set(0, -2.85, 0.26);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Initialize handlers and cleanup
  const timelines = [];
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    planeGeometry.dispose();
    planeMaterial.dispose();
    brushedMetalTexture.dispose();
  };

  return group;
}
